<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import api from'../services/api';import{setAuth}from'../stores';const email=ref(''),password=ref(''),error=ref(''),router=useRouter();async function submit(){try{const r=await api.post('/auth/login',{email:email.value,password:password.value});setAuth(r.data.user,r.data.token);router.push('/shop')}catch(e){error.value=e.response?.data?.message||'Sign in failed'}}}</script><template><div class="flex min-h-screen items-center justify-center bg-slate-950 p-4"><form @submit.prevent="submit" class="w-full max-w-md rounded-3xl bg-white p-8"><RouterLink to="/shop" class="text-xl font-black">Market<span class="text-indigo-600">Flow</span></RouterLink><h1 class="mt-10 text-3xl font-black">Welcome back</h1><input v-model="email" type="email" required placeholder="Email" class="mt-7 w-full rounded-xl border p-3"/><input v-model="password" type="password" required placeholder="Password" class="mt-3 w-full rounded-xl border p-3"/><p v-if="error" class="mt-3 text-sm text-red-600">{{error}}</p><button class="mt-5 w-full rounded-xl bg-indigo-600 py-3 font-bold text-white">Sign in</button><RouterLink class="mt-5 block text-center text-sm text-indigo-600" to="/register">Create account</RouterLink></form></div></template>